ext.badge.title:
.input {$count :number}
.match $count
0 {{auto : aucune facture à vérifier}}
one {{auto : {$count} facture à vérifier}}
* {{auto : {$count} factures à vérifier}}

ext.deposit.review.message:
.input {$count :number}
.match $count
0 {{{$summary} reçue : des points à contrôler dans auto.}}
one {{{$summary} reçue : {$count} point à contrôler dans auto.}}
* {{{$summary} reçue : {$count} points à contrôler dans auto.}}

ext.popup.some:
.input {$count :number}
.match $count
one {{{$company} : {$count} facture à vérifier.}}
* {{{$company} : {$count} factures à vérifier.}}

ext.popup.some_anonymous:
